fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since a and b have the same length, we can safely use zip to iterate over both simultaneously
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| x | y) // bitwise OR each pair
        .collect()             // collect results into a new Vec<u8>
}